-- Jeu de LecteurCabinets / EcrivainCabinets (« Cabinets », PROC_CABINET), lot 14 du plan-676a4b19. Identifiants 24004xx. Ce jeu est joue
-- AVANT ceux qui creent AUDIENCE_CABINET (PROC_COMPO, le premier), APPEL_AFFAIRE (PROC_COMPO) et CODE_CABINET (PROC_PREAUD) : il leur
-- donne la definition de ces jeux, plus les colonnes de RIG_DEV (AUDIENCE_CABINET.cs de RigBaseGreffe) que la creation d'un cabinet
-- ecrit, avec leur valeur par defaut de la V2 (les INSERT des autres jeux ne les nomment pas). TYPE_AUD_CAB : aucun autre jeu.
-- Le juge 1400501 (JUN14) et 1400502 (JDE14) sont ceux de PROC_CHM.sql, le greffier 1702511 (G17A) celui de PROC_COMPO.sql : joues apres
-- ce jeu, ils sont la quand le lecteur lit. Les lignes AUDNC_AUDIENCE = 0 des autres jeux n'ont pas de type : elles restent hors de l'ecran.
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_TYPE_AUD_CAB') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_TYPE_AUD_CAB varchar(5) NOT NULL CONSTRAINT DF_L14_AUDNC_TYPE DEFAULT ('');
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CODE_CABINET') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CODE_CABINET varchar(10) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_JUG') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_JUG int NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_GRASS') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_GRASS int NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_TYPE_CLASSEMENT_ADMIS') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_TYPE_CLASSEMENT_ADMIS varchar(128) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_NOMBRE_APPELS') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_NOMBRE_APPELS smallint NOT NULL CONSTRAINT DF_L14_AUDNC_NBAPP DEFAULT (0);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_NUM_APPEL_ATTRIB') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_NUM_APPEL_ATTRIB bit NOT NULL DEFAULT (0);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_PUBLIQUE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_PUBLIQUE bit NOT NULL CONSTRAINT DF_L14_AUDNC_PUBLIQUE DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ETAT_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ETAT_AUDIENCE varchar(1) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ETAT_CABINET') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ETAT_CABINET varchar(1) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_TOP_DIFFUSION') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_TOP_DIFFUSION bit NOT NULL CONSTRAINT DF_L14_AUDNC_TOP DEFAULT (0);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_NON_DISPONIBLE_WEB') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_NON_DISPONIBLE_WEB bit NOT NULL CONSTRAINT DF_L14_AUDNC_WEB DEFAULT (0);
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF OBJECT_ID(N'v2.CODE_CABINET') IS NULL
    CREATE TABLE v2.CODE_CABINET (R_CODECABINE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CODECABINE_LIBELLE_ECRAN varchar(35) NULL,
        R_CODECABINE_CALCUL_NUM_APPEL bit NULL, R_CODECABINE_PREAUD_INS_ASC bit NULL);
IF OBJECT_ID(N'v2.TYPE_AUD_CAB') IS NULL
    CREATE TABLE v2.TYPE_AUD_CAB (R_TYPEAUDCAB_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPEAUDCAB_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_TYPEAUDCAB_PARAMETRAGE_CABINET bit NOT NULL);

EXEC sp_executesql N'
-- L14T1 exige un code cabinet (R_TYPEAUDCAB_PARAMETRAGE_CABINET), L14T2 non (jumeau).
INSERT INTO v2.TYPE_AUD_CAB (R_TYPEAUDCAB_VALEUR, R_TYPEAUDCAB_LIBELLE_ECRAN, R_TYPEAUDCAB_PARAMETRAGE_CABINET) VALUES
    (''L14T1'', ''TYPE BANC CODE EXIGE'', 1), (''L14T2'', ''TYPE BANC LIBRE'', 0);
INSERT INTO v2.CODE_CABINET (R_CODECABINE_VALEUR, R_CODECABINE_LIBELLE_ECRAN) VALUES (''L14C1'', ''CABINET BANC UN''), (''L14C2'', ''CABINET BANC DEUX'');
INSERT INTO v2.AUDIENCE_CABINET (AUDNC_ID_ADNC, AUDNC_AUDIENCE, AUDNC_TYPE_AUD_CAB, AUDNC_CODE_CABINET, AUDNC_DATE, AUDNC_HEURE, AUDNC_ID_JUG, AUDNC_ID_GRASS) VALUES
    (2400401, 0, ''L14T1'', ''L14C1'', ''20990310'', ''09:00'', 1400501, 1702511),
    (2400402, 0, ''L14T2'', NULL, ''20200106'', ''14:00'', NULL, NULL),
    (2400403, 0, ''L14T2'', NULL, ''20200107'', NULL, NULL, NULL),
    -- Ecartee : une AUDIENCE (AUDNC_AUDIENCE = 1), jumelle de 2400401.
    (2400404, 1, ''L14T1'', ''L14C1'', ''20990311'', ''09:00'', 1400501, NULL),
    -- Un cabinet aux affaires appelees (APPEL_AFFAIRE 2400451) : date, type, code et juge actif en lecture seule.
    (2400405, 0, ''L14T1'', ''L14C2'', ''20200203'', ''09:30'', 1400502, NULL);
INSERT INTO v2.APPEL_AFFAIRE (APPAF_ID_APPAF, APPAF_ID_INSTN, APPAF_NUM_ORDRE, APPAF_ID_ADNC) VALUES (2400451, NULL, 1, 2400405);
';
